import { severityForStatus, urlPath } from "./network-event-format";
import { isWrapped, markWrapped } from "./patch-marker";
import type { RequestTraceContext, TraceContextManager } from "./trace-context";
import type { WebEvent } from "./types";

export interface NetworkCaptureOptions {
  emit(event: WebEvent): void;
  traceContext: TraceContextManager;
  /** Emit network events. */
  capture: boolean;
  /** Inject `traceparent` into allowlisted requests. */
  propagateTraceContext: boolean;
  /** Injection allowlist; empty means same-origin only. */
  allowlist: (string | RegExp)[];
  /** Response headers probed for a platform request id, in priority order. */
  requestIdHeaders: string[];
  /** SDK-internal endpoints: never captured, never injected. */
  isInternalUrl(url: string): boolean;
}

export interface NetworkCaptureHandle {
  teardown(): void;
}

const resolveUrl = (raw: string): string | undefined => {
  try {
    const url = new URL(raw, window.location.href);
    url.username = "";
    url.password = "";
    return url.href;
  } catch {
    return undefined;
  }
};

// ------------------------------------------------------------- activation --
// Patches install dormant (possibly via `@sazabi/browser/register` before
// any app module can capture the natives) and consult this slot per call.
// Undefined slot = transparent passthrough.

let active: NetworkCaptureOptions | undefined;

const isAllowedForInjection = (
  options: NetworkCaptureOptions,
  resolved: string,
): boolean => {
  if (options.allowlist.length === 0) {
    try {
      return new URL(resolved).origin === window.location.origin;
    } catch {
      return false;
    }
  }
  return options.allowlist.some((pattern) =>
    typeof pattern === "string"
      ? resolved.includes(pattern)
      : pattern.test(resolved),
  );
};

/** Injection eligibility for the active config; used by the resource observer
 * to decide whether a bypassed request is a diagnosable instrumentation gap. */
export const isActiveInjectionTarget = (resolved: string): boolean => {
  const options = active;
  if (!options?.propagateTraceContext) return false;
  if (options.isInternalUrl(resolved)) return false;
  return isAllowedForInjection(options, resolved);
};

// ----------------------------------------------------- wrapper-seen ledger --
// Every request processed by an active wrapper is recorded so the resource-
// timing observer can tell wrapper-captured traffic (skip: a richer event was
// already emitted) from traffic that bypassed the patches entirely.

interface SeenRequest {
  url: string;
  /** performance.now() timebase, comparable to PerformanceEntry.startTime. */
  startTime: number;
}

const SEEN_MATCH_WINDOW_MS = 5_000;
const SEEN_MAX_ENTRIES = 300;
let seenByWrapper: SeenRequest[] = [];

const recordWrapperRequest = (url: string): void => {
  seenByWrapper.push({ url, startTime: performance.now() });
  if (seenByWrapper.length > SEEN_MAX_ENTRIES) {
    seenByWrapper = seenByWrapper.slice(-SEEN_MAX_ENTRIES);
  }
};

/** Consume a wrapper-seen record matching this resource entry, if any. */
export const consumeWrapperSeen = (url: string, startTime: number): boolean => {
  const index = seenByWrapper.findIndex(
    (seen) =>
      seen.url === url &&
      Math.abs(seen.startTime - startTime) <= SEEN_MATCH_WINDOW_MS,
  );
  if (index === -1) return false;
  seenByWrapper.splice(index, 1);
  return true;
};

const emitNetworkEvent = (
  options: NetworkCaptureOptions,
  details: {
    kind: "fetch" | "xhr";
    method: string;
    resolvedUrl: string;
    status: number;
    durationMs: number;
    failureMessage?: string;
    injected?: RequestTraceContext;
    requestId?: string;
    requestIdHeader?: string;
  },
): void => {
  try {
    const path = urlPath(details.resolvedUrl);
    const outcome = details.status > 0 ? String(details.status) : "failed";
    const event: WebEvent = {
      type: "network",
      body: `${details.method} ${path} → ${outcome}`,
      severity: severityForStatus(details.status),
      timeUnixMs: Date.now(),
      attributes: {
        "http.request.method": details.method,
        "http.response.status_code":
          details.status > 0 ? details.status : undefined,
        "url.full": details.resolvedUrl,
        "web.network.kind": details.kind,
        "web.network.duration_ms": Math.round(details.durationMs),
        "web.network.error": details.failureMessage,
        "web.network.request_id": details.requestId,
        "web.network.request_id_header": details.requestIdHeader,
      },
    };
    if (details.injected) {
      event.traceId = details.injected.traceId;
      event.spanId = details.injected.spanId;
    }
    options.emit(event);
  } catch {
    // Capture failures must never surface to the host.
  }
};

const readFetchRequestId = (
  options: NetworkCaptureOptions,
  response: Response,
): { requestId?: string; requestIdHeader?: string } => {
  try {
    for (const name of options.requestIdHeaders) {
      const value = response.headers.get(name);
      if (value) return { requestId: value, requestIdHeader: name };
    }
  } catch {
    // Header access failures are ignorable detail loss.
  }
  return {};
};

const readXhrRequestId = (
  options: NetworkCaptureOptions,
  xhr: XMLHttpRequest,
): { requestId?: string; requestIdHeader?: string } => {
  try {
    for (const name of options.requestIdHeaders) {
      const value = xhr.getResponseHeader(name);
      if (value) return { requestId: value, requestIdHeader: name };
    }
  } catch {
    // Cross-origin/invalid-state header access — ignorable detail loss.
  }
  return {};
};

// ------------------------------------------------------------------ fetch --

interface FetchPatch {
  original: typeof fetch;
  wrapped: typeof fetch;
}

let fetchPatch: FetchPatch | undefined;

/**
 * Outermost-wins sandwich guard. When a third party patches fetch between our
 * register-time install and init (Sentry, analytics), init's re-wrap makes
 * the chain ourWrapper2(thirdParty(ourWrapper1(native))) — two ACTIVE copies
 * of our wrapper in one call path, which would double-emit every event. The
 * outermost wrapper raises this depth for the synchronous span of its
 * call-through; inner copies see it and become pure passthroughs.
 */
let fetchProcessingDepth = 0;

const makeWrappedFetch = (originalFetch: typeof fetch): typeof fetch => {
  const callThrough = (
    thisArg: unknown,
    input: RequestInfo | URL,
    init?: RequestInit,
  ): Promise<Response> => {
    fetchProcessingDepth++;
    try {
      return originalFetch.call(thisArg, input, init);
    } finally {
      fetchProcessingDepth--;
    }
  };

  return function (
    this: unknown,
    input: RequestInfo | URL,
    init?: RequestInit,
  ): Promise<Response> {
    const options = active;
    if (!options || fetchProcessingDepth > 0 || isWrapped(originalFetch)) {
      return originalFetch.call(this, input, init);
    }

    let resolvedUrl: string | undefined;
    let method = "GET";
    let injected: RequestTraceContext | undefined;
    let finalInit = init;

    try {
      const rawUrl =
        typeof input === "string"
          ? input
          : input instanceof URL
            ? input.href
            : input.url;
      resolvedUrl = resolveUrl(rawUrl);

      if (typeof input === "object" && "method" in input && input.method) {
        method = input.method.toUpperCase();
      }
      if (init?.method) {
        method = init.method.toUpperCase();
      }

      const internal =
        resolvedUrl === undefined || options.isInternalUrl(resolvedUrl);

      if (
        !internal &&
        resolvedUrl &&
        options.propagateTraceContext &&
        isAllowedForInjection(options, resolvedUrl)
      ) {
        const requestContext = options.traceContext.forRequest();

        if (input instanceof Request && init === undefined) {
          // Headers on a constructed Request are mutable for non-forbidden
          // names; if the guard rejects them, skip injection rather than
          // clone (cloning can consume one-shot bodies).
          try {
            for (const [name, value] of Object.entries(
              requestContext.headers,
            )) {
              if (!input.headers.has(name)) {
                input.headers.set(name, value);
              }
            }
            injected = requestContext;
          } catch {
            injected = undefined;
          }
        } else {
          // Per fetch semantics, init.headers replaces the Request's own
          // headers entirely. When the caller passed a Request plus an init
          // WITHOUT headers, seed the merge from the Request so injection
          // does not silently strip Authorization/Content-Type/etc.
          const merged =
            input instanceof Request && init?.headers === undefined
              ? new Headers(input.headers)
              : new Headers(init?.headers);
          let alreadyTraced = merged.has("traceparent");
          if (input instanceof Request && input.headers.has("traceparent")) {
            alreadyTraced = true;
          }
          if (!alreadyTraced) {
            for (const [name, value] of Object.entries(
              requestContext.headers,
            )) {
              merged.set(name, value);
            }
            finalInit = { ...init, headers: merged };
            injected = requestContext;
          }
        }
      }

      if (!internal && resolvedUrl !== undefined) {
        recordWrapperRequest(resolvedUrl);
      }

      if (internal || !options.capture || resolvedUrl === undefined) {
        return callThrough(this, input, finalInit);
      }
    } catch {
      // Any preparation failure: fall through to a plain passthrough call.
      return callThrough(this, input, init);
    }

    const start = performance.now();
    const capturedUrl = resolvedUrl;
    const capturedMethod = method;
    const capturedInjection = injected;

    return callThrough(this, input, finalInit).then(
      (response) => {
        emitNetworkEvent(options, {
          kind: "fetch",
          method: capturedMethod,
          resolvedUrl: capturedUrl,
          status: response.status,
          durationMs: performance.now() - start,
          injected: capturedInjection,
          ...readFetchRequestId(options, response),
        });
        return response;
      },
      (error: unknown) => {
        emitNetworkEvent(options, {
          kind: "fetch",
          method: capturedMethod,
          resolvedUrl: capturedUrl,
          status: 0,
          durationMs: performance.now() - start,
          failureMessage:
            error instanceof Error ? error.message : String(error),
          injected: capturedInjection,
        });
        throw error;
      },
    );
  };
};

// ------------------------------------------------------------------ XHR --

interface XhrRequestState {
  method: string;
  resolvedUrl?: string;
  customTraceparent: boolean;
  injected?: RequestTraceContext;
  start: number;
  /** Set by the outermost of our send wrappers in a third-party sandwich. */
  processed: boolean;
}

const xhrState = new WeakMap<XMLHttpRequest, XhrRequestState>();

interface XhrPatch {
  originalOpen: XMLHttpRequest["open"];
  originalSend: XMLHttpRequest["send"];
  originalSetRequestHeader: XMLHttpRequest["setRequestHeader"];
  wrappedOpen: XMLHttpRequest["open"];
  wrappedSend: XMLHttpRequest["send"];
  wrappedSetRequestHeader: XMLHttpRequest["setRequestHeader"];
}

let xhrPatch: XhrPatch | undefined;

const makeXhrPatch = (proto: XMLHttpRequest): XhrPatch => {
  const originalOpen = proto.open;
  const originalSend = proto.send;
  const originalSetRequestHeader = proto.setRequestHeader;

  // Forward `open` arguments with exact arity: `open(m, u, undefined)` would
  // coerce async to false (sync XHR) — not equivalent to the 2-arg call.
  const wrappedOpen = function (
    this: XMLHttpRequest,
    ...args: [string, string | URL, ...unknown[]]
  ): void {
    if (active) {
      try {
        const [method, url] = args;
        xhrState.set(this, {
          method: String(method).toUpperCase(),
          resolvedUrl: resolveUrl(String(url)),
          customTraceparent: false,
          start: 0,
          processed: false,
        });
      } catch {
        // Tracking failure must not affect the request.
      }
    }
    originalOpen.apply(this, args as Parameters<XMLHttpRequest["open"]>);
  };

  const wrappedSetRequestHeader = function (
    this: XMLHttpRequest,
    name: string,
    value: string,
  ): void {
    if (active) {
      try {
        if (name.toLowerCase() === "traceparent") {
          const tracked = xhrState.get(this);
          if (tracked) {
            tracked.customTraceparent = true;
          }
        }
      } catch {
        // Ignore.
      }
    }
    originalSetRequestHeader.call(this, name, value);
  };

  const wrappedSend = function (
    this: XMLHttpRequest,
    body?: Document | XMLHttpRequestBodyInit | null,
  ): void {
    const options = active;
    if (options) {
      try {
        const tracked = xhrState.get(this);
        // `processed` = an outer copy of our wrapper already handled this
        // send (third-party sandwich); inner copies must not re-inject or
        // attach a second loadend emitter.
        if (tracked?.resolvedUrl && !tracked.processed) {
          tracked.processed = true;
          const internal = options.isInternalUrl(tracked.resolvedUrl);

          if (
            !internal &&
            options.propagateTraceContext &&
            !tracked.customTraceparent &&
            isAllowedForInjection(options, tracked.resolvedUrl)
          ) {
            try {
              const requestContext = options.traceContext.forRequest();
              for (const [name, value] of Object.entries(
                requestContext.headers,
              )) {
                originalSetRequestHeader.call(this, name, value);
              }
              tracked.injected = requestContext;
            } catch {
              tracked.injected = undefined;
            }
          }

          if (!internal) {
            recordWrapperRequest(tracked.resolvedUrl);
          }

          if (!internal && options.capture) {
            tracked.start = performance.now();
            this.addEventListener("loadend", () => {
              const current = active ?? options;
              emitNetworkEvent(current, {
                kind: "xhr",
                method: tracked.method,
                resolvedUrl: tracked.resolvedUrl as string,
                status: this.status,
                durationMs: performance.now() - tracked.start,
                injected: tracked.injected,
                ...readXhrRequestId(current, this),
              });
            });
          }
        }
      } catch {
        // Fall through to the untouched send.
      }
    }
    originalSend.call(this, body);
  };

  return {
    originalOpen,
    originalSend,
    originalSetRequestHeader,
    wrappedOpen,
    wrappedSend,
    wrappedSetRequestHeader,
  };
};

// ----------------------------------------------------------------- install --

/**
 * Install dormant fetch/XHR patches around whatever implementations are
 * currently live. Idempotent, and re-wraps when a later actor (test stubs,
 * mocking layers) replaced the primitives after an earlier install — the
 * displaced wrapper is an inert passthrough, so single-processing holds.
 */
export const ensureNetworkPatches = (): void => {
  if (!isWrapped(window.fetch)) {
    const original = window.fetch;
    const wrapped = makeWrappedFetch(original);
    markWrapped(wrapped);
    window.fetch = wrapped;
    fetchPatch = { original, wrapped };
  }

  const proto = XMLHttpRequest.prototype;
  if (!isWrapped(proto.open)) {
    const patch = makeXhrPatch(proto);
    markWrapped(patch.wrappedOpen);
    markWrapped(patch.wrappedSetRequestHeader);
    markWrapped(patch.wrappedSend);
    proto.open = patch.wrappedOpen;
    proto.setRequestHeader = patch.wrappedSetRequestHeader;
    proto.send = patch.wrappedSend;
    xhrPatch = patch;
  }
};

/**
 * Restore the natives if the current implementations are still ours; if
 * someone patched on top of us, restoring would clobber them — the inactive
 * wrappers pass through.
 */
export const uninstallNetworkPatches = (): void => {
  if (fetchPatch && window.fetch === fetchPatch.wrapped) {
    window.fetch = fetchPatch.original;
  }
  fetchPatch = undefined;

  const proto = XMLHttpRequest.prototype;
  if (xhrPatch) {
    if (proto.open === xhrPatch.wrappedOpen) {
      proto.open = xhrPatch.originalOpen;
    }
    if (proto.setRequestHeader === xhrPatch.wrappedSetRequestHeader) {
      proto.setRequestHeader = xhrPatch.originalSetRequestHeader;
    }
    if (proto.send === xhrPatch.wrappedSend) {
      proto.send = xhrPatch.originalSend;
    }
  }
  xhrPatch = undefined;
  seenByWrapper = [];
};

export const installNetworkCapture = (
  options: NetworkCaptureOptions,
): NetworkCaptureHandle => {
  ensureNetworkPatches();
  active = options;

  return {
    teardown() {
      active = undefined;
    },
  };
};
