import type { EventSeverity } from "./types";

/** Compact display path: pathname when same-origin, host+path cross-origin. */
export const urlPath = (resolved: string): string => {
  try {
    const url = new URL(resolved);
    return url.origin === window.location.origin
      ? url.pathname
      : `${url.host}${url.pathname}`;
  } catch {
    return resolved;
  }
};

/** Status 0 means transport failure. */
export const severityForStatus = (status: number): EventSeverity => {
  if (status === 0 || status >= 500) return "ERROR";
  if (status >= 400) return "WARN";
  return "INFO";
};
